AssistantMessageToolRequest(name='create', tool_call_id='function-call-ae5926ce-058c-4d14-ba9e-2f63d8797399', arguments={'file_text': 'const { useState } = React;

const FormField = ({ label, id, type = "text", required = false, helperText, value, onChange }) => {
    return (
        <div className="form-field">
            <label htmlFor={id}>
                {label}
                {required && <span aria-hidden="true"> *</span>}
            </label>
            <input
                type={type}
                id={id}
                name={id}
                required={required}
                aria-required={required}
                aria-describedby={helperText ? `${id}-helper` : undefined}
                value={value}
                onChange={onChange}
            />
            {helperText && (
                <span id={`${id}-helper`} className="helper-text">
                    {helperText}
                </span>
            )}
        </div>
    );
};

const ContactForm = () => {
    const [formData, setFormData] = useState({
        fullName: "",
        email: "",
        phoneNumber: ""
    });

    const handleChange = (e) => {
        const { name, value } = e.target;
